<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!academy_ready())redirect('upgrade-multiverse-academy.php');$id=(int)($_GET['id']??0);$course=academy_by_id($id);if(!$course||!can_manage_course($course)){http_response_code(403);exit('You cannot manage this course.');}$tab=$_GET['tab']??'overview';$allowed=['overview','details','lessons','instructors','students','settings'];if(!in_array($tab,$allowed,true))$tab='overview';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
if($action==='save_details'){$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Course title is required.');$thumb=save_uploaded_image('thumbnail','academy/thumbnails',$id);$banner=save_uploaded_image('banner','academy/banners',$id);$sql='UPDATE academy_courses SET title=?,slug=?,subtitle=?,description=?,category=?,level=?,format=?,price=?,capacity=?,starts_at=?,ends_at=?,timezone=?'.($thumb?',thumbnail_path=?':'').($banner?',banner_path=?':'').' WHERE id=?';$args=[$title,academy_slug($title,$id),trim($_POST['subtitle']??''),trim($_POST['description']??''),trim($_POST['category']??'general'),$_POST['level']??'all_levels',$_POST['format']??'self_paced',(float)($_POST['price']??0),($_POST['capacity']??'')!==''?(int)$_POST['capacity']:null,($_POST['starts_at']??'')?:null,($_POST['ends_at']??'')?:null,trim($_POST['timezone']??'America/New_York')];if($thumb)$args[]=$thumb;if($banner)$args[]=$banner;$args[]=$id;db()->prepare($sql)->execute($args);flash('success','Course details saved.');$tab='details';}
elseif($action==='add_lesson'){$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Lesson title is required.');db()->prepare('INSERT INTO academy_lessons(course_id,title,lesson_type,summary,content,media_url,duration_minutes,sort_order,is_preview) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$title,$_POST['lesson_type']??'article',trim($_POST['summary']??''),trim($_POST['content']??''),trim($_POST['media_url']??''),($_POST['duration_minutes']??'')!==''?(int)$_POST['duration_minutes']:null,(int)($_POST['sort_order']??0),isset($_POST['is_preview'])?1:0]);flash('success','Lesson added.');$tab='lessons';}
elseif($action==='delete_lesson'){db()->prepare('DELETE FROM academy_lessons WHERE id=? AND course_id=?')->execute([(int)$_POST['lesson_id'],$id]);flash('success','Lesson removed.');$tab='lessons';}
elseif($action==='add_instructor'){$uid=(int)($_POST['user_id']??0);if($uid<1)throw new RuntimeException('Select a user.');db()->prepare('INSERT INTO academy_instructors(course_id,user_id,role) VALUES(?,?,?) ON DUPLICATE KEY UPDATE role=VALUES(role)')->execute([$id,$uid,$_POST['role']??'instructor']);flash('success','Instructor added.');$tab='instructors';}
elseif($action==='remove_instructor'){db()->prepare('DELETE FROM academy_instructors WHERE course_id=? AND user_id=? AND user_id<>?')->execute([$id,(int)$_POST['user_id'],(int)$course['owner_user_id']]);flash('success','Instructor removed.');$tab='instructors';}
elseif($action==='update_student'){$valid=['enrolled','waitlisted','in_progress','completed','cancelled'];$status=$_POST['status']??'';if(!in_array($status,$valid,true))throw new RuntimeException('Invalid enrollment status.');db()->prepare('UPDATE academy_enrollments SET status=?,progress_percent=?,completed_at=? WHERE course_id=? AND user_id=?')->execute([$status,max(0,min(100,(int)($_POST['progress_percent']??0))),$status==='completed'?date('Y-m-d H:i:s'):null,$id,(int)$_POST['user_id']]);flash('success','Student updated.');$tab='students';}
elseif($action==='save_settings'){$status=$_POST['status']??$course['status'];if((user()['role']??'')!=='admin')$status=$course['status'];db()->prepare('UPDATE academy_courses SET status=?,is_featured=? WHERE id=?')->execute([$status,((user()['role']??'')==='admin'&&isset($_POST['is_featured']))?1:0,$id]);flash('success','Course settings saved.');$tab='settings';}
}catch(Throwable $e){flash('error',$e->getMessage());}redirect_route('academy/manage.php',['id'=>$id,'tab'=>$tab]);}
$course=academy_by_id($id);$lessons=academy_lessons($id);$instructors=academy_instructors($id);$students=academy_students($id);$stats=academy_stats($id);$users=db()->query('SELECT id,display_name,email FROM users WHERE status="active" ORDER BY display_name')->fetchAll();app_header('Manage '.$course['title']);?><section class="dashboard-hero"><p class="eyebrow">COURSE MANAGEMENT</p><h1><?=e($course['title'])?></h1><p>Create lessons, manage instructors, and track learner progress.</p><p><a class="button ghost" href="view.php?slug=<?=urlencode($course['slug'])?>">View Public Course</a></p></section><nav class="management-tabs"><?php foreach(['overview'=>'Overview','details'=>'Details','lessons'=>'Lessons','instructors'=>'Instructors','students'=>'Students','settings'=>'Settings'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?id=<?=$id?>&tab=<?=$k?>"><?=$v?></a><?php endforeach?></nav>
<?php if($tab==='overview'):?><section class="dev-stat-grid"><article class="app-card dev-stat"><span>Lessons</span><strong><?=$stats['lessons']?></strong></article><article class="app-card dev-stat"><span>Students</span><strong><?=$stats['students']?></strong></article><article class="app-card dev-stat"><span>Completed</span><strong><?=$stats['completed']?></strong></article><article class="app-card dev-stat"><span>Average progress</span><strong><?=$stats['average']?>%</strong></article></section><section class="app-card"><h2>Course Status</h2><p><span class="badge"><?=e(ucfirst($course['status']))?></span> <span class="badge"><?=e(academy_formats()[$course['format']]??$course['format'])?></span></p></section>
<?php elseif($tab==='details'):?><section class="form-card wide"><h2>Course Details</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_details"><label>Title<input name="title" value="<?=e($course['title'])?>" required></label><label>Subtitle<input name="subtitle" value="<?=e($course['subtitle'])?>"></label><label>Category<input name="category" value="<?=e($course['category'])?>"></label><label>Level<select name="level"><?php foreach(academy_levels() as $k=>$v):?><option value="<?=$k?>" <?=$course['level']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>Format<select name="format"><?php foreach(academy_formats() as $k=>$v):?><option value="<?=$k?>" <?=$course['format']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>Price<input type="number" min="0" step="0.01" name="price" value="<?=e((string)$course['price'])?>"></label><label>Capacity<input type="number" min="1" name="capacity" value="<?=e((string)$course['capacity'])?>"></label><label>Timezone<input name="timezone" value="<?=e($course['timezone'])?>"></label><label>Starts<input type="datetime-local" name="starts_at" value="<?=e(academy_datetime_local($course['starts_at']))?>"></label><label>Ends<input type="datetime-local" name="ends_at" value="<?=e(academy_datetime_local($course['ends_at']))?>"></label><label>Thumbnail<input type="file" name="thumbnail" accept="image/*"></label><label>Banner<input type="file" name="banner" accept="image/*"></label><label class="full">Description<textarea name="description" rows="8"><?=e($course['description'])?></textarea></label><div class="full"><button class="button primary">Save Details</button></div></form></section>
<?php elseif($tab==='lessons'):?><div class="two-column-layout"><section class="app-card"><h2>Lessons</h2><?php foreach($lessons as $lesson):?><article class="lesson-row"><div><p class="eyebrow"><?=e(strtoupper(str_replace('_',' ',$lesson['lesson_type'])))?></p><h3><?=e($lesson['title'])?></h3><p><?=e($lesson['summary'])?></p></div><form method="post" onsubmit="return confirm('Remove this lesson?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_lesson"><input type="hidden" name="lesson_id" value="<?=(int)$lesson['id']?>"><button class="button danger small">Remove</button></form></article><?php endforeach?><?php if(!$lessons):?><p class="muted">No lessons yet.</p><?php endif?></section><aside class="app-card"><h2>Add Lesson</h2><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="add_lesson"><label>Title<input name="title" required></label><label>Type<select name="lesson_type"><?php foreach(academy_lesson_types() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Summary<textarea name="summary" rows="3"></textarea></label><label>Content<textarea name="content" rows="8"></textarea></label><label>Media URL<input type="url" name="media_url"></label><label>Duration (minutes)<input type="number" min="1" name="duration_minutes"></label><label>Order<input type="number" name="sort_order" value="0"></label><label class="check-row"><input type="checkbox" name="is_preview"> Free preview</label><button class="button primary">Add Lesson</button></form></aside></div>
<?php elseif($tab==='instructors'):?><div class="two-column-layout"><section class="app-card"><h2>Instructors</h2><?php foreach($instructors as $inst):?><article class="list-card"><div><strong><?=e($inst['display_name'])?></strong><p><?=e(ucfirst($inst['role']))?></p></div><?php if((int)$inst['user_id']!==(int)$course['owner_user_id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove_instructor"><input type="hidden" name="user_id" value="<?=(int)$inst['user_id']?>"><button class="button danger small">Remove</button></form><?php endif?></article><?php endforeach?></section><aside class="app-card"><h2>Add Instructor</h2><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="add_instructor"><label>User<select name="user_id"><?php foreach($users as $person):?><option value="<?=(int)$person['id']?>"><?=e($person['display_name'].' — '.$person['email'])?></option><?php endforeach?></select></label><label>Role<select name="role"><?php foreach(['lead','instructor','assistant','guest'] as $role):?><option value="<?=$role?>"><?=e(ucfirst($role))?></option><?php endforeach?></select></label><button class="button primary">Add Instructor</button></form></aside></div>
<?php elseif($tab==='students'):?><section class="app-card"><h2>Students</h2><div class="table-wrap"><table><thead><tr><th>Student</th><th>Status</th><th>Progress</th><th>Update</th></tr></thead><tbody><?php foreach($students as $student):?><tr><td><?=e($student['display_name'])?><br><small><?=e($student['email'])?></small></td><td><?=e(ucwords(str_replace('_',' ',$student['status'])))?></td><td><?=(int)$student['progress_percent']?>%</td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="update_student"><input type="hidden" name="user_id" value="<?=(int)$student['user_id']?>"><select name="status"><?php foreach(['enrolled','waitlisted','in_progress','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$student['status']===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach?></select><input type="number" name="progress_percent" min="0" max="100" value="<?=(int)$student['progress_percent']?>"><button class="button primary small">Save</button></form></td></tr><?php endforeach?></tbody></table></div><?php if(!$students):?><p class="muted">No students enrolled yet.</p><?php endif?></section>
<?php elseif($tab==='settings'):?><section class="form-card"><h2>Course Settings</h2><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><?php if((user()['role']??'')==='admin'):?><label>Status<select name="status"><?php foreach(['draft','pending','approved','rejected','archived'] as $status):?><option value="<?=$status?>" <?=$course['status']===$status?'selected':''?>><?=e(ucfirst($status))?></option><?php endforeach?></select></label><label class="check-row"><input type="checkbox" name="is_featured" <?=$course['is_featured']?'checked':''?>> Featured course</label><?php else:?><p>Approval status: <strong><?=e(ucfirst($course['status']))?></strong></p><?php endif?><button class="button primary">Save Settings</button></form></section><?php endif?><?php app_footer();
